function readClients(){let saved=[];try{const value=JSON.parse(localStorage.getItem(CLIENTS_KEY)||'[]');if(Array.isArray(value))saved=value}catch{}const canonicalIds=new Set(DEVELOPMENT_CLIENTS.map(client=>client.id)),savedById=new Map(saved.map(client=>[client.id,client])),savedBySlug=new Map(saved.map(client=>[client.slug,client])),merged=[...saved.filter(client=>!canonicalIds.has(client.id)&&!DEVELOPMENT_CLIENTS.some(seed=>seed.slug===client.slug)),...DEVELOPMENT_CLIENTS.map(client=>{const stored=savedById.get(client.id)||savedBySlug.get(client.slug);return{...client,...stored,admin:{...client.admin,...stored?.admin}}})];localStorage.setItem(CLIENTS_KEY,JSON.stringify(merged));return merged}
