  const values=()=>Object.fromEntries(api.tokenKeys.map(key=>[key,form.elements[key].value]));
  const sync=()=>{const state=api.readState();$$('[data-theme-mode]').forEach(button=>{const active=button.dataset.themeMode===state.mode;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active)});$$('[data-edit-mode]').forEach(button=>{const active=button.dataset.editMode===editMode;button.classList.toggle('active',active);button.setAttribute('aria-selected',active)});fill(state[editMode]);renderPresets()};
