function clientRow(client){const active=client.status==='active',profile=normalizeServiceProfile(client.serviceProfile||{preset:'quick'}),preset=SERVICE_PRESETS[profile.preset],serviceLabel=profile.serviceModes.length===2?'Quick + Table':preset.name;return `<article class="platform-client-row" data-client-id="${esc(client.id)}"><div class="platform-client"><span>${esc(client.businessName.charAt(0).toUpperCase())}.</span><div><strong>${esc(client.businessName)}</strong><small>${esc(serviceLabel)} · ${esc(profile.locationName)}</small></div></div><code>${esc(client.prefix)}.</code><span class="platform-status${active?'':' inactive'}">${active?'Active':'Paused'}</span><div class="platform-row-actions"><button class="button primary" type="button" data-open-client>Admin workspace</button><button class="button outline" type="button" data-configure-client>Configure</button><a class="button outline" href="/menu/?business=${encodeURIComponent(client.slug)}">Customer view</a><button class="button subtle" type="button" data-toggle-client>${active?'Pause':'Activate'}</button></div></article>`}
function adminRow(client){return `<article class="platform-account-row"><div><strong>${esc(client.admin.name)}</strong><small>${esc(client.admin.email)}</small></div><span>${esc(client.businessName)}</span><code>${esc(client.admin.username)}</code><span class="platform-status">${esc(client.admin.access||'First login pending')}</span></article>`}
