function enhanceGlassSelects(scope=document){scope.querySelectorAll('select:not([hidden]):not([data-glass-ready])').forEach(select=>{select.dataset.glassReady='true';select.classList.add('glass-native-select');const button=document.createElement('button');button.type='button';button.className='glass-select-trigger';button.dataset.glassSelect='';button.setAttribute('aria-haspopup','listbox');button.innerHTML=`<span>${esc(select.options[select.selectedIndex]?.text||'Choose')}</span><i aria-hidden="true">⌄</i>`;select.insertAdjacentElement('afterend',button)})}
