function renderGateBoards(modeFilter){const form=$('#client-form');form.elements.serviceModeQuick.checked=serviceBuilder.modes.has('quick');form.elements.serviceModeTable.checked=serviceBuilder.modes.has('table');const target=$('#gate-boards');if(target){target.innerHTML=['quick','table'].filter(mode=>serviceBuilder.modes.has(mode)&&(!modeFilter||mode===modeFilter)).map(mode=>{const active=serviceBuilder.gates[mode],available=GATES[mode].filter(([id])=>!active.includes(id));return`<section class="gate-board" data-gate-mode="${mode}"><header><strong>Gate order</strong><span>${active.length} gates</span></header><div class="gate-list" data-gate-list="${mode}">${active.map((id,index)=>{const meta=gateMeta(mode,id);return`<article class="gate-item" draggable="true" data-gate-id="${id}"><button class="gate-grip" type="button" data-move-gate="${id}" aria-label="Move ${esc(meta[1])} down">↕</button><button class="gate-main" type="button" data-configure-gate="${id}"><strong><span>${index+1}</span>${esc(meta[1])}</strong><small>${esc(gateSummary(id,serviceBuilder.settings))}</small></button><button class="gate-remove" type="button" data-remove-gate="${id}" aria-label="Remove ${esc(meta[1])}">×</button></article>`}).join('')||'<p class="gate-empty">No gates yet. Add one below.</p>'}</div><div class="gate-add"><select aria-label="Add ${mode} gate">${available.map(([id,label])=>`<option value="${id}">${esc(label)}</option>`).join('')}</select><button class="button outline" type="button" data-add-gate="${mode}"${available.length?'':' disabled'}>Add gate</button></div></section>`}).join('');enhanceGlassSelects(target)}updateFormPreviews()}
