function readServiceProfile(){const modes=[...serviceBuilder.modes],settings={...serviceBuilder.settings,serviceMode:modes.includes('table')?'table':'quick',serviceModes:modes,gateOrder:{quick:[...serviceBuilder.gates.quick],table:[...serviceBuilder.gates.table]}};if(modes.includes('quick')){for(const [gate,key,fallback] of [['consumption','consumptionModes',['dine_in']],['fulfillment','fulfillmentModes',['pickup']],['quick_payment','paymentModes',['counter']]])settings[key]=serviceBuilder.gates.quick.includes(gate)?settings[key]||fallback:fallback;settings.locatorMode=serviceBuilder.gates.quick.includes('locator')?settings.locatorMode||'table':'none'}if(modes.includes('table')){settings.guestCountRequired=serviceBuilder.gates.table.includes('party_size');settings.bundleSelection=serviceBuilder.gates.table.includes('bundle')?settings.bundleSelection||'required':'none';settings.packageMode=settings.bundleSelection==='required'?'required':'none';settings.entryPayment=serviceBuilder.gates.table.includes('entry_payment')?settings.entryPayment||'deposit':'none';settings.entitlementMode=serviceBuilder.gates.table.includes('entitlement')?settings.entitlementMode||'bundle':'none';settings.timeLimitMinutes=serviceBuilder.gates.table.includes('time_limit')?Number(settings.timeLimitMinutes)||90:0;settings.quantityLimit=serviceBuilder.gates.table.includes('quantity_limit')?Number(settings.quantityLimit)||1:0;settings.additionalDevices=serviceBuilder.gates.table.includes('joining');settings.joinPolicy=settings.additionalDevices?settings.joinPolicy||'host':'disabled';settings.billLocksOrdering=serviceBuilder.gates.table.includes('bill_closure')&&settings.billLocksOrdering!==false}return normalizeServiceProfile({preset:serviceBuilder.preset,serviceModes:modes,locationName:$('#client-form').elements.locationName.value.trim()||'Main location',settings})}
function updateFormPreviews(){const form=$('#client-form'),name=form.elements.businessName.value,slug=segment(form.elements.slug.value||name),prefix=usernameSegment(form.elements.prefix.value||segment(name).split('-')[0]),suffix=usernameSegment(form.elements.adminUsername.value)||'admin',profile=readServiceProfile(),journeys=profile.serviceModes.map(mode=>`${mode==='quick'?'Quick':'Table'}: ${profile.settings.gateOrder[mode].map(id=>gateMeta(mode,id)?.[1]).join(' → ')||'no gates'}`);$('#journey-preview').textContent=`${profile.locationName} · ${journeys.join(' · ')}`;$('#business-details-summary').textContent=name?`${name} · ${profile.locationName}`:'Name, location and portal';$('#business-services-summary').textContent=profile.serviceModes.map(mode=>mode==='quick'?'Quick':'Table').join(' + ');$('#quick-settings-row').hidden=!profile.serviceModes.includes('quick');$('#table-settings-row').hidden=!profile.serviceModes.includes('table');$('#quick-settings-summary').textContent=`${profile.settings.gateOrder.quick.length} gates`;$('#table-settings-summary').textContent=`${profile.settings.gateOrder.table.length} gates`;$('#client-admin-summary').textContent=form.elements.adminName.value||'Initial account';return{slug,prefix,suffix}}
