$('#platform-continue').addEventListener('click',()=>{$('#platform-login').hidden=true;$('#platform-shell').hidden=false;showView('overview');render()});
$('#platform-logout').addEventListener('click',()=>{$('#platform-shell').hidden=true;$('#platform-login').hidden=false;document.title='QRK MENU — QRK Admin';$('#platform-continue').focus()});
document.addEventListener('click',async event=>{const view=event.target.closest('[data-admin-view]');if(view)showView(view.dataset.adminView);if(event.target.closest('[data-add-client]'))openClientDialog();const configure=event.target.closest('[data-configure-client]');if(configure){const id=configure.closest('[data-client-id]').dataset.clientId;openClientDialog(clients.find(client=>client.id===id))}if(event.target.closest('.close-dialog'))event.target.closest('dialog').close();const openClient=event.target.closest('[data-open-client]');if(openClient){const id=openClient.closest('[data-client-id]').dataset.clientId,client=clients.find(item=>item.id===id);try{await authService.signInDevelopment({displayName:client.admin.name,username:client.admin.username,businessId:`preview:${client.slug}`,businessName:client.businessName,businessSlug:client.slug,serviceMode:client.serviceProfile.settings.serviceMode,role:'admin',permissions:{viewOrders:true,acceptOrders:true,prepareOrders:true,markReady:true,completeOrders:true,cancelOrders:true,changeAvailability:true,editMenu:true,viewOrderHistory:true,viewSales:true,manageStaff:true}});location.href='/'}catch(reason){announce(reason.message)}}const toggle=event.target.closest('[data-toggle-client]');if(toggle){const id=toggle.closest('[data-client-id]').dataset.clientId,client=clients.find(item=>item.id===id);client.status=client.status==='active'?'paused':'active';saveClients();render();announce(`${client.businessName} ${client.status==='active'?'activated':'paused'} in this preview`)}});
const clientForm=$('#client-form');
clientForm.elements.businessName.addEventListener('input',event=>{if(!clientForm.elements.slug.dataset.edited)clientForm.elements.slug.value=segment(event.target.value);if(!clientForm.elements.prefix.dataset.edited)clientForm.elements.prefix.value=usernameSegment(segment(event.target.value).split('-')[0]);updateFormPreviews()});
clientForm.elements.slug.addEventListener('input',event=>{event.target.dataset.edited='true';event.target.value=segment(event.target.value);updateFormPreviews()});clientForm.elements.prefix.addEventListener('input',event=>{event.target.dataset.edited='true';event.target.value=usernameSegment(event.target.value);updateFormPreviews()});clientForm.elements.adminUsername.addEventListener('input',event=>{event.target.value=usernameSegment(event.target.value);updateFormPreviews()});clientForm.addEventListener('reset',()=>{delete clientForm.elements.slug.dataset.edited;delete clientForm.elements.prefix.dataset.edited;requestAnimationFrame(updateFormPreviews)});
function setSheetHeader(title,backType=''){const close=$('#close-client-sheet');$('#client-sheet-title').textContent=title;close.textContent=backType?'‹':'×';close.setAttribute('aria-label',backType?'Back':'Close');close.dataset.backSheet=backType}
function openClientSheet(type){closeGlassSelect();const form=clientForm,body=$('#client-sheet-body'),title={business:'Business details',services:'Business services',quick:'Quick settings',table:'Table settings',admin:'Client Admin'}[type];setSheetHeader(title);if(type==='business')body.innerHTML=`<div class="sheet-form-group">${[['businessName','Business name'],['locationName','First location'],['slug','Portal slug'],['prefix','Username prefix']].map(([key,label])=>field(label,`<input data-draft-field="${key}" value="${esc(form.elements[key].value)}">`)).join('')}</div>`;if(type==='admin')body.innerHTML=`<div class="sheet-form-group">${[['adminName','Full name'],['adminEmail','Email address'],['adminUsername','Username suffix']].map(([key,label])=>field(label,`<input data-draft-field="${key}" value="${esc(form.elements[key].value)}">`)).join('')}</div>`;if(type==='services')body.innerHTML=`<div class="sheet-choice-list"><label><span><strong>Quick</strong><small>Counter, pickup or simple fulfillment</small></span><input type="checkbox" data-service-mode="quick"${serviceBuilder.modes.has('quick')?' checked':''}></label><label><span><strong>Table</strong><small>Sessions, hosts, bills and entitlements</small></span><input type="checkbox" data-service-mode="table"${serviceBuilder.modes.has('table')?' checked':''}></label></div>`;if(['quick','table'].includes(type)){const options=Object.values(SERVICE_PRESETS).filter(preset=>preset.id!=='custom'&&preset.settings.serviceMode===type).map(preset=>`<option value="${preset.id}">${esc(preset.name)}</option>`).join('');body.innerHTML=`<div class="sheet-preset-row"><select id="sheet-preset-choice" aria-label="Starting preset">${options}</select><button class="button outline" type="button" id="apply-service-preset">Apply preset</button><button class="button subtle" type="button" id="start-empty-service" data-empty-mode="${type}">Start empty</button></div><div class="gate-boards" id="gate-boards"></div>`;renderGateBoards(type);enhanceGlassSelects(body)}const sheet=$('#client-sheet');sheet.hidden=false;sheet.dataset.sheetType=type;requestAnimationFrame(()=>sheet.classList.add('open'))}
function openGateSheet(mode,id){closeGlassSelect();const meta=gateMeta(mode,id);setSheetHeader(meta[1],mode);const body=$('#client-sheet-body');body.innerHTML=`<p class="sheet-context">${mode==='quick'?'Quick':'Table'} gate</p><div class="sheet-form-group gate-fields">${gateControls(id,serviceBuilder.settings)}</div>`;enhanceGlassSelects(body)}
function closeClientSheet(){const sheet=$('#client-sheet');sheet.classList.remove('open');setTimeout(()=>sheet.hidden=true,220);updateFormPreviews()}
document.addEventListener('click',event=>{const glassTrigger=event.target.closest('[data-glass-select]');if(glassTrigger){openGlassSelect(glassTrigger.previousElementSibling,glassTrigger);return}const glassOption=event.target.closest('[data-glass-option]');if(glassOption){const layer=glassOption.closest('.glass-choice-layer'),select=layer._select;select.value=glassOption.dataset.glassOption;select.nextElementSibling.querySelector('span').textContent=select.options[select.selectedIndex].text;select.dispatchEvent(new Event('change',{bubbles:true}));closeGlassSelect();return}if(event.target.closest('[data-close-glass-select]')){closeGlassSelect();return}const opener=event.target.closest('[data-open-client-sheet]');if(opener){openClientSheet(opener.dataset.openClientSheet);return}const sheetClose=event.target.closest('#close-client-sheet');if(sheetClose){sheetClose.dataset.backSheet?openClientSheet(sheetClose.dataset.backSheet):closeClientSheet();return}if(event.target.closest('#done-client-sheet')){closeClientSheet();return}if(event.target.closest('#apply-service-preset')){applyPreset($('#sheet-preset-choice').value);return}const configureGate=event.target.closest('[data-configure-gate]');if(configureGate){openGateSheet(configureGate.closest('[data-gate-mode]').dataset.gateMode,configureGate.dataset.configureGate);return}const empty=event.target.closest('#start-empty-service');if(empty){const mode=empty.dataset.emptyMode;serviceBuilder.preset='custom';serviceBuilder.gates[mode]=[];renderGateBoards(mode);return}const move=event.target.closest('[data-move-gate]');if(move){const mode=move.closest('[data-gate-mode]').dataset.gateMode,order=serviceBuilder.gates[mode],at=order.indexOf(move.dataset.moveGate),next=(at+1)%order.length;order.splice(next,0,order.splice(at,1)[0]);renderGateBoards(mode);return}const remove=event.target.closest('[data-remove-gate]');if(remove){const mode=remove.closest('[data-gate-mode]').dataset.gateMode;serviceBuilder.gates[mode]=serviceBuilder.gates[mode].filter(id=>id!==remove.dataset.removeGate);renderGateBoards(mode);return}const add=event.target.closest('[data-add-gate]');if(add){const mode=add.dataset.addGate,id=add.closest('.gate-add').querySelector('select').value;if(id)serviceBuilder.gates[mode].push(id);renderGateBoards(mode)}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.querySelector('.glass-choice-layer')){event.preventDefault();closeGlassSelect()}});
clientForm.addEventListener('change',event=>{const serviceMode=event.target.dataset.serviceMode;if(serviceMode){event.target.checked?serviceBuilder.modes.add(serviceMode):serviceBuilder.modes.delete(serviceMode);if(!serviceBuilder.modes.size){serviceBuilder.modes.add(serviceMode);event.target.checked=true}if(event.target.checked&&!serviceBuilder.gates[serviceMode].length)serviceBuilder.gates[serviceMode]=orderFor(presetSettings(serviceMode==='quick'?'quick':'traditional'))[serviceMode];clientForm.elements[serviceMode==='quick'?'serviceModeQuick':'serviceModeTable'].checked=event.target.checked;updateFormPreviews();return}const fieldName=event.target.dataset.gateField;if(fieldName){serviceBuilder.settings[fieldName]=event.target.type==='checkbox'?event.target.checked:event.target.type==='number'?Number(event.target.value):fieldName.endsWith('Modes')?csv(event.target.value):event.target.value;if(fieldName==='entryAmount'){serviceBuilder.settings.entryAmountMinor=Number(event.target.value)*100;serviceBuilder.settings.minimumSpendMinor=Number(event.target.value)*100}updateFormPreviews()}});clientForm.addEventListener('input',event=>{const draft=event.target.dataset.draftField;if(draft){clientForm.elements[draft].value=draft==='slug'?segment(event.target.value):draft==='prefix'||draft==='adminUsername'?usernameSegment(event.target.value):event.target.value;if(draft==='businessName'){if(!clientForm.elements.slug.value)clientForm.elements.slug.value=segment(event.target.value);if(!clientForm.elements.prefix.value)clientForm.elements.prefix.value=usernameSegment(segment(event.target.value).split('-')[0])}updateFormPreviews()}const fieldName=event.target.dataset.gateField;if(fieldName){serviceBuilder.settings[fieldName]=event.target.type==='number'?Number(event.target.value):fieldName.endsWith('Modes')?csv(event.target.value):event.target.value;updateFormPreviews()}});
let draggedGate=null;document.addEventListener('dragstart',event=>{const item=event.target.closest('[data-gate-id]');if(!item)return;draggedGate={mode:item.closest('[data-gate-mode]').dataset.gateMode,id:item.dataset.gateId};item.classList.add('dragging')});document.addEventListener('dragend',event=>{event.target.closest('[data-gate-id]')?.classList.remove('dragging');draggedGate=null});document.addEventListener('dragover',event=>{const item=event.target.closest('[data-gate-id]');if(item&&draggedGate?.mode===item.closest('[data-gate-mode]').dataset.gateMode)event.preventDefault()});document.addEventListener('drop',event=>{const item=event.target.closest('[data-gate-id]');if(!item||!draggedGate)return;event.preventDefault();const order=serviceBuilder.gates[draggedGate.mode],from=order.indexOf(draggedGate.id),to=order.indexOf(item.dataset.gateId);if(from>=0&&to>=0){order.splice(to,0,order.splice(from,1)[0]);renderGateBoards(draggedGate.mode)}});
clientForm.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget,businessName=form.elements.businessName.value.trim(),slug=segment(form.elements.slug.value),prefix=usernameSegment(form.elements.prefix.value),suffix=usernameSegment(form.elements.adminUsername.value),username=`${prefix}.${suffix}`,error=$('#client-form-error'),current=clients.find(client=>client.id===editingClientId);error.textContent='';if(!businessName||!slug||!prefix||!form.elements.adminName.value.trim()||!form.elements.adminEmail.value.trim()||!suffix){error.textContent='Complete the business and Client Admin details.';return}if(clients.some(client=>client.id!==editingClientId&&client.slug===slug)){error.textContent='That portal slug is already in use.';return}if(clients.some(client=>client.id!==editingClientId&&client.prefix===prefix)){error.textContent='That username prefix is already in use.';return}const record={businessName,slug,prefix,serviceProfile:readServiceProfile(),admin:{...(current?.admin||{}),name:form.elements.adminName.value.trim(),email:form.elements.adminEmail.value.trim(),username}};if(current){Object.assign(current,record);saveClients();render();$('#client-dialog').close();announce(`${businessName} settings saved`);return}let credentials;try{credentials=authService.createPreviewUser({displayName:record.admin.name,username,email:record.admin.email,role:'admin',permissions:{viewOrders:true,acceptOrders:true,prepareOrders:true,markReady:true,completeOrders:true,cancelOrders:true,changeAvailability:true,editMenu:true,viewOrderHistory:true,viewSales:true,manageStaff:true},businessId:`preview:${slug}`,businessName,businessSlug:slug,active:true})}catch(reason){error.textContent=reason.message;return}clients.push({id:`client-${Date.now()}`,...record,status:'active',createdAt:new Date().toISOString(),admin:{...record.admin,access:'First login pending'}});saveClients();render();$('#client-dialog').close();$('#created-admin-username').textContent=credentials.username;$('#created-admin-password').textContent=credentials.temporaryPassword;$('#credentials-dialog').showModal();announce(`${businessName} client portal created`)});
$('#copy-client-login').addEventListener('click',async()=>{const value=`QRK MENU Client Admin login\nUsername: ${$('#created-admin-username').textContent}\nTemporary password: ${$('#created-admin-password').textContent}\nPortal: ${location.origin}/`;try{await navigator.clipboard.writeText(value);announce('Client Admin login copied')}catch{announce('Copy the login details shown')}});initializeThemeEditor();render();
